import gurobipy as gp
from gurobipy import GRB
suppliers = ['MOUNT AYR', 'WAUKEE', 'WAVERLY', 'PELLA', 'DES MOINES']
customers = ['Customer_1', 'Customer_2', 'Customer_3', 'Customer_4', 'Customer_5']
demand = {'Customer_1': 2397, 'Customer_2': 1889, 'Customer_3': 2518, 'Customer_4': 3218, 'Customer_5': 1813}
fixed_cost = {'MOUNT AYR': 96.58, 'WAUKEE': 94.06, 'WAVERLY': 94.37, 'PELLA': 82.88, 'DES MOINES': 94.96}
cost = {'MOUNT AYR': {'Customer_1': 694.68, 'Customer_2': 17.48, 'Customer_3': 20.07, 'Customer_4': 199.02, 'Customer_5': 1685.53}, 'WAUKEE': {'Customer_1': 15.13, 'Customer_2': 1.5, 'Customer_3': 1.43, 'Customer_4': 27.88, 'Customer_5': 90.69}, 'WAVERLY': {'Customer_1': 2.34, 'Customer_2': 349.34, 'Customer_3': 246.6, 'Customer_4': 41.3, 'Customer_5': 78.73}, 'PELLA': {'Customer_1': 1181.6, 'Customer_2': 1458.53, 'Customer_3': 1646.36, 'Customer_4': 1924.55, 'Customer_5': 38.93}, 'DES MOINES': {'Customer_1': 1030.8, 'Customer_2': 43.48, 'Customer_3': 932.43, 'Customer_4': 55.39, 'Customer_5': 103.84}}
M = sum(demand.values())
for f in suppliers:
    if f not in fixed_cost:
        raise ValueError(f'Missing fixed cost for supplier {f}')
    if f not in cost:
        raise ValueError(f'Missing cost row for supplier {f}')
    for s in customers:
        if s not in cost[f]:
            raise ValueError(f'Missing cost for supplier {f}, customer {s}')
for s in customers:
    if s not in demand:
        raise ValueError(f'Missing demand for customer {s}')
m = gp.Model('Iowa_Liquor_FLP')
x_vars = m.addVars(suppliers, customers, lb=0, vtype=GRB.CONTINUOUS, name='')
y_vars = m.addVars(suppliers, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((cost[f][s] * x_vars[f, s] for f in suppliers for s in customers)) + gp.quicksum((fixed_cost[f] * y_vars[f] for f in suppliers)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[f, s] for f in suppliers)) == demand[s] for s in customers), name='')
m.addConstrs((gp.quicksum((x_vars[f, s] for s in customers)) <= M * y_vars[f] for f in suppliers), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')
